pub mod cyclic_progress;
pub mod format;
pub mod progress_display;

pub use self::cyclic_progress::CyclicProgress;
pub use self::format::Format;
pub use self::progress_display::ProgressDisplay;

use super::format::Format;

const SPINNER_FRAMES: [&str; 8] = ["⣾", "⣽", "⣻", "⢿", "⡿", "⣟", "⣯", "⣷"];

#[derive(Clone, Debug)]
pub struct CyclicProgress {
    total: u32,
    current: u32,
}

impl CyclicProgress {
    pub fn new(total: u32) -> Self {
        Self { total, current: 0 }
    }

    pub fn next(&mut self) {
        if self.total == 0 {
            return;
        }

        self.current = (self.current + 1) % self.total;
    }

    pub fn str(&self) -> String {
        let frame = SPINNER_FRAMES[(self.current as usize) % SPINNER_FRAMES.len()];
        format!("{frame} {}", Format::percentage(self.ratio()))
    }

    fn ratio(&self) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            self.current as f32 / self.total as f32
        }
    }
}

pub struct Format;

impl Format {
    pub fn percentage(value: f32) -> String {
        Self::percentage_with_precision(value, 1)
    }

    pub fn percentage_with_precision(value: f32, precision: usize) -> String {
        format!(
            "{value:.precision$}%",
            value = value * 100.0_f32,
            precision = precision
        )
    }

    pub fn progress(current: u32, total: u32) -> String {
        format!("{current}/{total}")
    }
}

use super::format::Format;

#[derive(Clone, Debug)]
pub struct ProgressDisplay {
    total: u32,
    current: u32,
}

impl ProgressDisplay {
    pub fn new(total: u32) -> Self {
        Self { total, current: 0 }
    }

    pub fn update(&mut self, value: u32) {
        self.current = value;
    }

    pub fn increment(&mut self, delta: u32) {
        self.current = self.current.saturating_add(delta);
    }

    pub fn display(&self) -> String {
        format!(
            "Progress: {} ({})",
            Format::percentage(self.ratio()),
            Format::progress(self.current, self.total)
        )
    }

    fn ratio(&self) -> f32 {
        if self.total == 0 {
            0.0
        } else {
            self.current as f32 / self.total as f32
        }
    }
}
